using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Windows.Forms;
using System.Drawing;
namespace MoOLVaMaster {
sealed class CopyPlan {
 public readonly List<string> Files=new List<string>(); public readonly List<string> Errors=new List<string>(); public long Bytes;
 public void Scan(string root){if((File.GetAttributes(root)&FileAttributes.ReparsePoint)!=0){Errors.Add("Исходная папка является ссылкой: "+root);return;}Walk(root,root);}
 void Walk(string root,string dir){try{foreach(string entry in Directory.GetFileSystemEntries(dir)){try{var a=File.GetAttributes(entry);if((a&FileAttributes.ReparsePoint)!=0){Errors.Add("Пропущена ссылка: "+entry);continue;}if((a&FileAttributes.Directory)!=0)Walk(root,entry);else{Files.Add(entry);Bytes+=new FileInfo(entry).Length;}}catch(Exception e){Errors.Add(entry+": "+e.Message);}}}catch(Exception e){Errors.Add(dir+": "+e.Message);}}
}
static class BackupEngine {
 public static bool Same(string a,string b){using(var sha=SHA256.Create())using(var x=File.OpenRead(a))using(var y=File.OpenRead(b))return sha.ComputeHash(x).SequenceEqual(sha.ComputeHash(y));}
 public static bool Within(string child,string parent){string a=Path.GetFullPath(child).TrimEnd('\\')+"\\",b=Path.GetFullPath(parent).TrimEnd('\\')+"\\";return a.StartsWith(b,StringComparison.OrdinalIgnoreCase);}
 public static string BackupKey(string source){using(var h=SHA256.Create()){byte[] data=System.Text.Encoding.UTF8.GetBytes(Path.GetFullPath(source).TrimEnd('\\').ToUpperInvariant());return BitConverter.ToString(h.ComputeHash(data)).Replace("-","").Substring(0,12);}}
 public static void RejectLinks(string path){string current=Path.GetFullPath(path);while(!String.IsNullOrEmpty(current)){if((Directory.Exists(current)||File.Exists(current))&&(File.GetAttributes(current)&FileAttributes.ReparsePoint)!=0)throw new IOException("Папка назначения содержит ссылку: "+current);string parent=Path.GetDirectoryName(current);if(String.IsNullOrEmpty(parent)||String.Equals(parent,current,StringComparison.OrdinalIgnoreCase))break;current=parent;}}
 public static string Copy(string source,string target,CopyPlan p,Action<string> progress){
  if(Within(target,source)||Within(source,target))throw new IOException("Папки источника и назначения пересекаются.");
  int ok=0,skipped=0;var errors=new List<string>(p.Errors);string baseDir=Path.GetFullPath(source).TrimEnd('\\')+"\\";
  foreach(string file in p.Files){try{if(!Within(file,source))throw new IOException("Путь вне исходной папки");string relative=file.Substring(baseDir.Length),dest=Path.Combine(target,relative);if(!Within(dest,target))throw new IOException("Путь вне папки назначения");RejectLinks(Path.GetDirectoryName(dest));Directory.CreateDirectory(Path.GetDirectoryName(dest));RejectLinks(Path.GetDirectoryName(dest));if(File.Exists(dest)){if(Same(file,dest)){ok++;continue;}skipped++;errors.Add("Не перезаписан существующий файл: "+dest);continue;}string temp=dest+".moolva-"+Guid.NewGuid().ToString("N")+".part";try{File.Copy(file,temp,false);if(!Same(file,temp))throw new IOException("Контрольная сумма не совпала");File.Move(temp,dest);ok++;}finally{if(File.Exists(temp))File.Delete(temp);}}catch(Exception e){skipped++;errors.Add(file+": "+e.Message);}progress("Проверено: "+(ok+skipped)+" / "+p.Files.Count);}
  return "Проверены и скопированы: "+ok+"\r\nПропущены / ошибки: "+(skipped+p.Errors.Count)+"\r\n"+String.Join("\r\n",errors);
 }
 public static bool SelfTest(){string root=Path.Combine(Path.GetTempPath(),"moolva-backup-test-"+Guid.NewGuid().ToString("N"));try{string a=Path.Combine(root,"source"),b=Path.Combine(root,"backup");Directory.CreateDirectory(a);File.WriteAllText(Path.Combine(a,"test.txt"),"один");var p=new CopyPlan();p.Scan(a);Copy(a,b,p,_=>{});if(!Same(Path.Combine(a,"test.txt"),Path.Combine(b,"test.txt")))return false;File.WriteAllText(Path.Combine(a,"test.txt"),"другой");Copy(a,b,p,_=>{});return File.ReadAllText(Path.Combine(b,"test.txt"))=="один"&&Within(Path.Combine(a,"file"),a)&&!Within(b,a)&&BackupKey(a)==BackupKey(a.ToUpperInvariant())&&BackupKey(a)!=BackupKey(b);}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
}
sealed class BackupWindow:Form {
 readonly CheckedListBox folders=new CheckedListBox();readonly TextBox output=new TextBox();readonly Button go=new Button();readonly List<KeyValuePair<string,string>> sources=new List<KeyValuePair<string,string>>();bool busy;
 public BackupWindow(){Text="Резервное копирование файлов — MoOLVa";Size=new Size(850,720);StartPosition=FormStartPosition.CenterParent;var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(15)};Controls.Add(flow);flow.Controls.Add(new Label{Text="Выберите папки. Используйте отдельный диск, который не будете форматировать.",Width=760,Height=45});folders.Width=760;folders.Height=120;flow.Controls.Add(folders);Add("Рабочий стол",Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory));Add("Документы",Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments));Add("Изображения",Environment.GetFolderPath(Environment.SpecialFolder.MyPictures));Add("Загрузки",Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads"));var add=new Button{Text="Добавить папку",Width=220,Height=40};flow.Controls.Add(add);add.Click+=(s,e)=>{using(var d=new FolderBrowserDialog())if(d.ShowDialog()==DialogResult.OK)Add("Своя папка "+(sources.Count+1),d.SelectedPath);};go.Text="Выбрать диск и начать";go.Width=260;go.Height=45;flow.Controls.Add(go);go.Click+=async(s,e)=>await Start();var restore=new Button{Text="Восстановить папку из копии",Width=260,Height=40};flow.Controls.Add(restore);restore.Click+=async(s,e)=>await Restore();output.Width=760;output.Height=280;output.Multiline=true;output.ScrollBars=ScrollBars.Vertical;output.ReadOnly=true;flow.Controls.Add(output);FormClosing+=(s,e)=>{if(busy){e.Cancel=true;MessageBox.Show("Дождитесь завершения копирования.");}};}
 void Add(string name,string path){if(!String.IsNullOrEmpty(path)&&Directory.Exists(path)){sources.Add(new KeyValuePair<string,string>(name,path));folders.Items.Add(name+" — "+path,true);}}
 async Task Restore(){using(var a=new FolderBrowserDialog{Description="Выберите папку внутри резервной копии"}){if(a.ShowDialog()!=DialogResult.OK)return;using(var b=new FolderBrowserDialog{Description="Выберите папку, в которую вернуть файлы"}){if(b.ShowDialog()!=DialogResult.OK)return;try{if(BackupEngine.Within(a.SelectedPath,b.SelectedPath)||BackupEngine.Within(b.SelectedPath,a.SelectedPath))throw new IOException("Источник и назначение пересекаются.");busy=true;go.Enabled=false;output.Text="Проверка файлов...";var plan=await Task.Run(()=>{var p=new CopyPlan();p.Scan(a.SelectedPath);return p;});long free=new DriveInfo(Path.GetPathRoot(b.SelectedPath)).AvailableFreeSpace;if(plan.Bytes>free)throw new IOException("Недостаточно свободного места.");if(MessageBox.Show("Будет проверено и скопировано файлов: "+plan.Files.Count+". Существующие отличающиеся файлы будут пропущены. Продолжить?","Восстановление",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;var progress=new Progress<string>(x=>output.Text=x);output.Text=await Task.Run(()=>BackupEngine.Copy(a.SelectedPath,b.SelectedPath,plan,x=>((IProgress<string>)progress).Report(x)));MessageBox.Show("Проверьте отчёт, особенно пропущенные файлы.");}catch(Exception ex){output.Text="Ошибка восстановления: "+ex.Message;}finally{busy=false;go.Enabled=true;}}}}
 async Task Start(){var selected=folders.CheckedIndices.Cast<int>().Select(i=>sources[i]).ToList();if(selected.Count==0){MessageBox.Show("Выберите папки.");return;}using(var d=new FolderBrowserDialog{Description="Выберите отдельный диск или папку для резервной копии"}){if(d.ShowDialog()!=DialogResult.OK)return;string target=Path.Combine(d.SelectedPath,"MoOLVa-Backup-"+Environment.MachineName);try{foreach(var s in selected)if(BackupEngine.Within(target,s.Value)||BackupEngine.Within(s.Value,target))throw new IOException("Папка копии пересекается с исходной папкой.");busy=true;go.Enabled=false;output.Text="Расчёт объёма...";var plans=await Task.Run(()=>selected.Select(s=>{var p=new CopyPlan();p.Scan(s.Value);return p;}).ToList());long size=plans.Sum(p=>p.Bytes);long needed=await Task.Run(()=>{long n=0;for(int k=0;k<selected.Count;k++){string root=Path.GetFullPath(selected[k].Value).TrimEnd('\\')+"\\";string dst=Path.Combine(target,"папка-"+BackupEngine.BackupKey(selected[k].Value));foreach(string src in plans[k].Files){string dest=Path.Combine(dst,src.Substring(root.Length));if(!File.Exists(dest))n+=new FileInfo(src).Length;}}return n;});long free=new DriveInfo(Path.GetPathRoot(target)).AvailableFreeSpace;int errors=plans.Sum(p=>p.Errors.Count);string preflight="Найдено: "+(size/1073741824.0).ToString("N2")+" ГБ; дополнительно потребуется до "+(needed/1073741824.0).ToString("N2")+" ГБ; свободно: "+(free/1073741824.0).ToString("N2")+" ГБ; пропущено при проверке: "+errors;output.Text=preflight+"\r\n"+String.Join("\r\n",plans.SelectMany(p=>p.Errors).Take(50));if(needed>free){MessageBox.Show("Недостаточно свободного места.");return;}if(MessageBox.Show(preflight+"\r\nПодробнее о пропусках — в окне.\r\nКопировать в "+target+"? Существующие отличающиеся файлы не перезаписываются.","Копия",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;var messages=new List<string>();var prog=new Progress<string>(x=>output.Text=x);for(int i=0;i<selected.Count;i++){var source=selected[i];var plan=plans[i];string folder=Path.Combine(target,"папка-"+BackupEngine.BackupKey(source.Value));messages.Add(source.Value+" → "+folder+"\r\n"+await Task.Run(()=>BackupEngine.Copy(source.Value,folder,plan,x=>((IProgress<string>)prog).Report(x))));}Directory.CreateDirectory(target);string report=String.Join("\r\n\r\n",messages);File.WriteAllText(Path.Combine(target,"MoOLVa-Backup-Report.txt"),report,System.Text.Encoding.UTF8);output.Text=report;MessageBox.Show("Операция завершена. Проверьте отчёт на наличие пропусков.");}catch(Exception ex){output.Text="Ошибка: "+ex.Message;}finally{busy=false;go.Enabled=true;}}}
}
sealed class PackageWindow:Form {
 readonly CheckedListBox items=new CheckedListBox();readonly TextBox log=new TextBox();readonly Button start=new Button();readonly HashSet<string> selected=new HashSet<string>(StringComparer.OrdinalIgnoreCase);bool busy,filtering;
 readonly string[] ids={"Google.Chrome","7zip.7zip","Telegram.TelegramDesktop","VideoLAN.VLC","Mozilla.Firefox","Notepad++.Notepad++","Adobe.Acrobat.Reader.64-bit"};
 public PackageWindow(){Text="Программы — MoOLVa";Size=new Size(820,650);StartPosition=FormStartPosition.CenterParent;var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(15)};Controls.Add(flow);flow.Controls.Add(new Label{Text="Установка через WinGet. Для некоторых пакетов могут потребоваться действия и принятие условий в окне установщика.",Width=740,Height=45});var search=new TextBox{Width=740};flow.Controls.Add(new Label{Text="Поиск по каталогу",AutoSize=true});flow.Controls.Add(search);items.Width=740;items.Height=160;foreach(string id in ids)items.Items.Add(id);flow.Controls.Add(items);items.ItemCheck+=(s,e)=>{if(filtering)return;string id=Convert.ToString(items.Items[e.Index]);if(e.NewValue==CheckState.Checked)selected.Add(id);else selected.Remove(id);};search.TextChanged+=(s,e)=>{filtering=true;try{items.Items.Clear();foreach(string id in ids)if(id.IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0)items.Items.Add(id,selected.Contains(id));}finally{filtering=false;}};start.Text="Установить выбранное";start.Width=250;start.Height=40;flow.Controls.Add(start);log.Width=740;log.Height=290;log.Multiline=true;log.ScrollBars=ScrollBars.Vertical;log.ReadOnly=true;flow.Controls.Add(log);start.Click+=async(s,e)=>await Install();FormClosing+=(s,e)=>{if(busy){e.Cancel=true;MessageBox.Show("Дождитесь завершения установки.");}};}
 async Task Install(){var chosen=ids.Where(id=>selected.Contains(id)).ToArray();if(chosen.Length==0){MessageBox.Show("Отметьте программы.");return;}busy=true;start.Enabled=false;try{for(int i=0;i<chosen.Length;i++){string id=chosen[i];log.AppendText((i+1)+" / "+chosen.Length+" — "+id+"\r\n");int result=await Task.Run(()=>{var psi=new ProcessStartInfo("winget.exe","install --id "+id+" --exact --source winget --disable-interactivity"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=Process.Start(psi)){var stdout=p.StandardOutput.ReadToEndAsync();var stderr=p.StandardError.ReadToEndAsync();p.WaitForExit();Task.WaitAll(stdout,stderr);return p.ExitCode;}});log.AppendText(id+": "+(result==0?"готово":"не выполнено, код "+result)+"\r\n");}}catch(Exception ex){log.AppendText("Ошибка запуска WinGet: "+ex.Message+"\r\n");}finally{busy=false;start.Enabled=true;}}
}
}
